243→// ---------------------------------------------------------------------------
244→// Types
245→// ---------------------------------------------------------------------------
246→
247→type ActionData =
248→  | { ok: true; message: string; redirectId?: string }
249→  | { error: string };
250→
251→// ---------------------------------------------------------------------------
252→// Constants
253→// ---------------------------------------------------------------------------
254→
255→const CATEGORY_LABELS: Record<string, string> = {
256→  tops: "Tops",
257→  bottoms: "Bottoms",
258→  dresses: "Dresses",
259→  shoes: "Shoes",
260→  kids: "Kids",
261→  rings: "Rings",
262→  sportswear: "Sportswear",
263→  general: "General",
264→};
265→
266→const CATEGORY_ICONS: Record<string, string> = {
267→  tops: "👕",
268→  bottoms: "👖",
269→  dresses: "👗",
270→  shoes: "👟",
271→  kids: "🧒",
272→  rings: "💍",
273→  sportswear: "🏃",
274→  general: "📏",
275→};
276→
277→// ---------------------------------------------------------------------------
278→// Helpers
279→// ---------------------------------------------------------------------------
280→
281→function formatDate(date: string | Date): string {
282→  return new Date(date).toLocaleDateString("en-US", {
283→    month: "short",
284→    day: "numeric",
285→    year: "numeric",
286→  });
287→}
288→
289→// ---------------------------------------------------------------------------
290→// Sub-components
291→// ---------------------------------------------------------------------------
292→
293→interface TemplateSectionProps {
294→  templates: Array<{ name: string; category: string; gender: string; rowCount: number }>;
295→  categories: string[];
296→  isLoading: boolean;
297→  onClose: () => void;
298→  fetcher: ReturnType<typeof useFetcher<typeof action>>;
299→}
300→
301→function TemplatePicker({ templates, categories, isLoading, onClose, fetcher }: TemplateSectionProps) {
302→  const [selectedCategory, setSelectedCategory] = useState<string>("all");
303→
304→  const filteredTemplates = selectedCategory === "all"
305→    ? templates
306→    : templates.filter((t) => t.category === selectedCategory);
307→
308→  return (
309→    <div
310→      style={{
311→        position: "fixed",
312→        inset: 0,
313→        zIndex: 999,
314→        background: "rgba(0,0,0,0.5)",
315→        display: "flex",
316→        alignItems: "center",
317→        justifyContent: "center",
318→        padding: "24px",
319→      }}
320→      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
321→    >
322→      <div
323→        style={{
324→          background: "#fff",
325→          borderRadius: "16px",
326→          width: "100%",
327→          maxWidth: "780px",
328→          maxHeight: "85vh",
329→          display: "flex",
330→          flexDirection: "column",
331→          overflow: "hidden",
332→          boxShadow: "0 20px 60px rgba(0,0,0,0.2)",
333→        }}
334→      >
335→        {/* Modal header */}
336→        <div style={{ padding: "20px 24px", borderBottom: "1px solid #e3e3e3", flexShrink: 0 }}>
337→          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
338→            <div>
339→              <p style={{ margin: 0, fontSize: "17px", fontWeight: 650, color: "#202223" }}>
340→                Create a size chart
341→              </p>
342→              <p style={{ margin: "4px 0 0", fontSize: "13px", color: "#6d7175" }}>
343→                Start from scratch or choose a pre-filled template
344→              </p>
345→            </div>
346→            <s-button variant="tertiary" onClick={onClose}>Close</s-button>
347→          </div>
348→        </div>
349→
350→        {/* Category filter tabs */}
351→        <div style={{ padding: "12px 24px", borderBottom: "1px solid #f1f1f1", flexShrink: 0 }}>
352→          <s-button-group>
353→            <s-button
354→              variant={selectedCategory === "all" ? "primary" : "tertiary"}
355→              onClick={() => setSelectedCategory("all")}
356→            >
357→              All
358→            </s-button>
359→            {categories.map((cat) => (
360→              <s-button
361→                key={cat}
362→                variant={selectedCategory === cat ? "primary" : "tertiary"}
363→                onClick={() => setSelectedCategory(cat)}
364→              >
365→                {CATEGORY_ICONS[cat] ?? "📏"} {CATEGORY_LABELS[cat] ?? cat}
366→              </s-button>
367→            ))}
368→          </s-button-group>
369→        </div>
370→
371→        {/* Scrollable body */}
372→        <div style={{ flex: 1, overflow: "auto", padding: "20px 24px" }}>
373→          {/* Blank chart card */}
374→          <div style={{ marginBottom: "24px" }}>
375→            <s-box padding="base" borderWidth="base" borderRadius="base">
376→              <s-stack direction="inline" gap="base">
377→                <s-stack direction="block" gap="small-200">
378→                  <s-text><strong>Blank chart</strong></s-text>
379→                  <s-text color="subdued">Start with an empty table — add your own columns and sizes</s-text>
380→                </s-stack>
381→                <fetcher.Form method="post">
382→                  <input type="hidden" name="intent" value="create-blank" />
383→                  <input type="hidden" name="name" value="Untitled Size Chart" />
384→                  <input type="hidden" name="category" value="general" />
385→                  <s-button type="submit" loading={isLoading}>Create blank</s-button>
386→                </fetcher.Form>
387→              </s-stack>
388→            </s-box>
389→          </div>
390→
391→          {/* Template grid */}
392→          <div
393→            style={{
394→              display: "grid",
395→              gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
396→              gap: "12px",
397→            }}
398→          >
399→            {filteredTemplates.map((template) => (
400→              <s-box key={template.name} padding="base" borderWidth="base" borderRadius="base">
401→                <s-stack direction="block" gap="small-200">
402→                  <s-stack direction="inline" gap="small-200">
403→                    <s-text>{CATEGORY_ICONS[template.category] ?? "📏"}</s-text>
404→                    <s-text><strong>{template.name}</strong></s-text>
405→                  </s-stack>
406→                  <s-stack direction="inline" gap="small-200">
407→                    <s-badge tone="info">{CATEGORY_LABELS[template.category] ?? template.category}</s-badge>
408→                    <s-text color="subdued">{template.rowCount} sizes</s-text>
409→                  </s-stack>
410→                  <fetcher.Form method="post">
411→                    <input type="hidden" name="intent" value="create-from-template" />
412→                    <input type="hidden" name="templateName" value={template.name} />
413→                    <s-button variant="primary" type="submit" loading={isLoading}>
414→                      Use template
415→                    </s-button>
416→                  </fetcher.Form>
417→                </s-stack>
418→              </s-box>
419→            ))}
420→          </div>
421→
422→          {filteredTemplates.length === 0 && (
423→            <s-stack direction="block" gap="base">
424→              <s-text color="subdued">No templates in this category.</s-text>
425→            </s-stack>
426→          )}
427→        </div>
428→      </div>
429→    </div>
430→  );
431→}
