433→// ---------------------------------------------------------------------------
434→// Main component
435→// ---------------------------------------------------------------------------
436→
437→export default function SizeCharts() {
438→  const { charts, plan, templates, categories, canCreate } =
439→    useLoaderData<typeof loader>();
440→  const fetcher = useFetcher<typeof action>();
441→  const shopify = useAppBridge();
442→
443→  const [showTemplates, setShowTemplates] = useState(false);
444→  const [showImport, setShowImport] = useState(false);
445→  const [importName, setImportName] = useState("Imported Size Chart");
446→  const [importCategory, setImportCategory] = useState("general");
447→  const [importCsvText, setImportCsvText] = useState("");
448→  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
449→  const [categoryFilter, setCategoryFilter] = useState("all");
450→  const [searchQuery, setSearchQuery] = useState("");
451→
452→  const isLoading = fetcher.state !== "idle";
453→
454→  useEffect(() => {
455→    if (!fetcher.data) return;
456→    const data = fetcher.data as ActionData;
457→    if ("ok" in data && data.ok) {
458→      shopify.toast.show(data.message);
459→      if ("redirectId" in data && data.redirectId) {
460→        window.location.href = `/app/size-charts/${data.redirectId}`;
461→      } else {
462→        setShowTemplates(false);
463→        setShowImport(false);
464→        setImportCsvText("");
465→        setImportName("Imported Size Chart");
466→      }
467→    } else if ("error" in data) {
468→      shopify.toast.show(data.error, { isError: true });
469→    }
470→  }, [fetcher.data, shopify]);
471→
472→  const filteredCharts = charts.filter((chart) => {
473→    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
474→    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
475→    const matchesSearch =
476→      searchQuery.trim() === "" ||
477→      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
478→    return matchesStatus && matchesCategory && matchesSearch;
479→  });
480→
481→  const publishedCount = charts.filter((c) => c.status === "active").length;
482→  const draftCount = charts.filter((c) => c.status === "draft").length;
483→  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
484→  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
485→  const maxCharts = plan.limits.maxCharts;
486→  const isFreePlan = plan.id === "free";
487→
488→  const progressPct =
489→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
490→  const progressColor =
491→    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";
492→
493→  function clearFilters() {
494→    setStatusFilter("all");
495→    setCategoryFilter("all");
496→    setSearchQuery("");
497→  }
498→
499→  return (
500→    <s-page heading="Size Charts">
501→      {/* Primary action */}
502→      <s-button
503→        slot="primary-action"
504→        variant="primary"
505→        onClick={() => setShowTemplates(!showTemplates)}
506→        disabled={!canCreate || isLoading}
507→      >
508→        {canCreate
509→          ? showTemplates
510→            ? "Cancel"
511→            : "Create chart"
512→          : `Limit reached (${plan.limits.maxCharts})`}
513→      </s-button>
514→
515→      <s-button
516→        slot="secondary-action"
517→        onClick={() => { setShowImport(!showImport); setShowTemplates(false); }}
518→      >
519→        Import CSV
520→      </s-button>
521→
522→      {/* ================================================================ */}
523→      {/* PLAN LIMIT BANNER                                                 */}
524→      {/* ================================================================ */}
525→      {!canCreate && (
526→        <s-section>
527→          <s-banner tone="warning" heading="Chart limit reached">
528→            You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
529→            {plan.name} plan. Upgrade to Starter for unlimited charts with no
530→            hidden fees.{" "}
531→            <s-button href="/app/pricing" variant="primary">
532→              Upgrade plan
533→            </s-button>
534→          </s-banner>
535→        </s-section>
536→      )}
537→
538→      {/* Template picker modal — rendered outside page flow */}
539→      {showTemplates && (
540→        <TemplatePicker
541→          templates={templates}
542→          categories={categories}
543→          isLoading={isLoading}
544→          onClose={() => setShowTemplates(false)}
545→          fetcher={fetcher}
546→        />
547→      )}
548→
549→      {/* ================================================================ */}
550→      {/* CSV IMPORT PANEL                                                  */}
551→      {/* ================================================================ */}
552→      {showImport && (
553→        <s-section>
554→          <s-box padding="base" borderWidth="base" borderRadius="base">
555→            <s-stack direction="block" gap="base">
556→              {/* Header row */}
557→              <s-stack direction="inline" gap="base">
558→                <s-stack direction="block" gap="small-200">
559→                  <s-heading>Import Size Chart from CSV</s-heading>
560→                  <s-text color="subdued">
561→                    Paste your CSV data below. The first row must be column headers (e.g. Size, Chest, Waist).
562→                  </s-text>
563→                </s-stack>
564→                <s-button variant="tertiary" onClick={() => setShowImport(false)}>Close</s-button>
565→              </s-stack>
566→
567→              {/* CSV format hint */}
568→              <s-box padding="base" borderWidth="base" borderRadius="base">
569→                <s-stack direction="block" gap="small-200">
570→                  <s-text color="subdued">
571→                    <strong>Expected CSV format</strong>
572→                  </s-text>
573→                  <code style={{ fontSize: "12px", color: "#5c5f62", lineHeight: 1.7, display: "block", whiteSpace: "pre" }}>{`Size,Chest,Waist,Hips\nXS,32-34,24-26,34-36\nS,34-36,26-28,36-38\nM,36-38,28-30,38-40`}</code>
574→                </s-stack>
575→              </s-box>
576→
577→              {/* Name + category row */}
578→              <s-stack direction="inline" gap="base">
579→                <div style={{ flex: 2, minWidth: "180px" }}>
580→                  <s-text-field
581→                    label="Chart name"
582→                    value={importName}
583→                    onChange={(e: Event) => setImportName((e.target as HTMLInputElement).value)}
584→                    placeholder="e.g. Women's Tops"
585→                  />
586→                </div>
587→                <div style={{ flex: 1, minWidth: "140px" }}>
588→                  <s-select
589→                    label="Category"
590→                    value={importCategory}
591→                    onChange={(e: Event) =>
592→                      setImportCategory((e.target as HTMLSelectElement).value)
593→                    }
594→                  >
595→                    <s-option value="general">General</s-option>
596→                    <s-option value="tops">Tops</s-option>
597→                    <s-option value="bottoms">Bottoms</s-option>
598→                    <s-option value="dresses">Dresses</s-option>
599→                    <s-option value="shoes">Shoes</s-option>
600→                    <s-option value="kids">Kids</s-option>
601→                    <s-option value="rings">Rings</s-option>
602→                    <s-option value="sportswear">Sportswear</s-option>
